outputs = ['xzfdh', 'wgude', 'hudewi', 'fz', 'iuxu']

# Test rule 1: 'k' -> 'z'
rules = [('k', 'z')]
result = []
for inp in inputs:
    out = inp.replace('k', 'z')
    result.append(out)

print("Testing rule 'k' -> 'z':")
for i, (inp, out, expected) in enumerate(zip(inputs, result, outputs)):
    status = "✓" if out == expected else "✗"
    print(f"  {status} '{inp}' -> '{out}' (expected '{expected}')")

